// Monta lembrete pro CLIENTE (24h ou 2h antes) com tom natural
const reunioes = items.filter(i => i.json && i.json.id && i.json.tipo_lembrete);
if (!reunioes.length) return [];

function fmtHora(dt) {
  const d = new Date(dt);
  return String(d.getUTCHours()).padStart(2,'0') + ':' + String(d.getUTCMinutes()).padStart(2,'0');
}
function fmtData(dt) {
  const d = new Date(dt);
  return String(d.getUTCDate()).padStart(2,'0') + '/' + String(d.getUTCMonth()+1).padStart(2,'0');
}

return reunioes.map(r => {
  const j = r.json;
  const primeiroNome = (j.nome_cliente || '').split(' ')[0];
  const oi = primeiroNome ? `Oi ${primeiroNome}, tudo bem?` : 'Oi, tudo bem?';
  const hora = fmtHora(j.agendado_para);
  let texto;
  if (j.tipo_lembrete === '24h') {
    texto = `${oi} Aqui e a Giulia, secretaria do Thiago Nicezio. Passando pra lembrar da conversa de voces amanha (${fmtData(j.agendado_para)}) as ${hora}. Confirmado? Se precisar remarcar, me avisa por aqui.`;
  } else {
    texto = `${oi} Lembrando que a conversa com o Thiago Nicezio e daqui a pouco, as ${hora}. Ate ja!`;
  }
  const flag = j.tipo_lembrete === '24h' ? 'lembrete_24h_enviado' : 'lembrete_2h_enviado';
  return {
    json: {
      send_to: String(j.numero_cliente).replace(/[^0-9]/g,''),
      send_text: texto,
      finalize_sql: `UPDATE giulia_reunioes SET ${flag} = TRUE WHERE id = ${j.id};`
    }
  };
});
